import { Suspense, lazy, useState } from 'react';
import { Plus, ArrowUpRight, ArrowDownLeft, ArrowRight, CalendarDays, Search, ChevronRight, Trophy, NotebookPen, Trash2, Pencil, SlidersHorizontal, LayoutGrid, List, Shirt as ShirtIcon, Flag, Wallet, Goal, CircleDot, BriefcaseBusiness, Clock3, Save, Binoculars } from 'lucide-react';
import { PageHeader, SectionTitle, Empty, TextLink, Crest, Shirt, TrophyArt } from './ui';
const Locker3D = lazy(() => import('./Locker3D').then(module => ({ default: module.Locker3D })));
import { stats, playerStats, matchResult, money, compactMoney, shortDate, formations, balance, nextSeason, seasonLabel, today, uid, isAvailable, DEFAULT_LOCKER_STYLE, type Career, type Match, type Player, type Note, type ScoutReport, type AcademyProspect, type CareerGoal, type MuseumItem } from './model';
export type Page = 'home'|'locker'|'lineup'|'games'|'office'|'finance'|'trophies'|'history'|'seasons'|'scout'|'academy'|'objectives';
export type Open = (type:'match'|'player'|'trophy'|'note'|'transaction'|'transfer'|'settings',id?:string)=>void;
type Props = {career:Career;open:Open;update:(c:Career)=>void};
const Add = ({children,onClick}:{children:React.ReactNode;onClick:()=>void})=><button className="button primary" onClick={onClick}><Plus size={17}/>{children}</button>;
export function MatchRow({match,career,onClick}:{match:Match;career:Career;onClick:()=>void}) {const result=matchResult(match);return <button className="match-row" onClick={onClick}><div className="match-day"><strong>{new Date(match.date+'T12:00:00').getDate()}</strong><span>{new Date(match.date+'T12:00:00').toLocaleDateString('pt-PT',{month:'short'})}</span></div><Crest club={match.opponent} color="#999e8d" size={31}/><div className="match-opponent"><strong>{match.opponent}</strong><span>{match.competition} · {match.venue==='home'?'Casa':'Fora'}</span></div>{match.status==='played'?<><span className="match-score">{match.goalsFor}<i>:</i>{match.goalsAgainst}</span><span className={`result result-${result}`}>{result}</span></>:<span className="scheduled-label">Por jogar</span>}<ChevronRight size={16}/></button>;}
export function Home({career:c,open,go}:Props&{go:(p:Page)=>void}){
 const s=stats(c);const ps=playerStats(c,c.playerId);const active=c.players.filter(isAvailable);const recent=c.matches.filter(m=>m.status==='played').sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4);const next=c.matches.filter(m=>m.status==='scheduled').sort((a,b)=>a.date.localeCompare(b.date))[0]; const star=c.players.find(p=>p.id===c.playerId)??c.players.find(p=>p.position==='PL')??c.players[0];
 const leaders=c.players.map(p=>({...p,stats:playerStats(c,p.id)})).sort((a,b)=>b.stats.goals-a.stats.goals).filter(p=>p.stats.played>0).slice(0,3);
 return <><PageHeader eyebrow={`${c.game} / ÉPOCA ${c.season}`} title={c.mode==='player'?'O teu próximo capítulo.':'O jogo começa aqui.'} description={`${c.person}, bem-vindo${c.gender==='female'?'':' de volta'} ao teu ${c.mode==='player'?'percurso':'clube'}.`} action={<Add onClick={()=>open('match')}>Adicionar jogo</Add>}/><div className="home-hero"><div className="home-hero-bg"/><div className="home-hero-copy"><span className="eyebrow"><span className="live-dot"/> {c.mode==='player'?'A TUA CAMISOLA. A TUA HISTÓRIA.':'UMA EQUIPA. UMA IDENTIDADE.'}</span><h2>{c.mode==='player'?c.person:c.club}<span>O legado constrói-se<br/>a cada jornada.</span></h2><button className="button cream" onClick={()=>go('locker')}>Entrar no balneário<ArrowUpRight size={18}/></button><div className="hero-meta"><span>{c.mode==='player'?'CARREIRA DE JOGADOR':'CARREIRA DE TREINADOR'}</span><i/>{c.gender==='male'?'MASCULINO':'FEMININO'}</div></div><div className="hero-shirt"><div className="shirt-hanger"/><Shirt color={c.color} number={star?.number??10} name={star?.name??c.person} back/><span>{c.mode==='player'?c.person:'A camisola pesa. A história inspira.'}</span></div><span className="hero-large-year">{c.season.split('/')[1]}</span></div><div className="stats-grid">{(c.mode==='player'?[{label:'JOGOS DISPUTADOS',value:ps.played,detail:`${ps.minutes} minutos em campo`,icon:<CalendarDays/>},{label:'GOLOS',value:ps.goals,detail:'Cada um tem uma história',icon:<Goal/>},{label:'ASSISTÊNCIAS',value:ps.assists,detail:'O último passe conta',icon:<CircleDot/>},{label:'NOTA MÉDIA',value:ps.rating?ps.rating.toFixed(1):'—',detail:'Dos jogos avaliados',icon:<Flag/>}]:[{label:'JOGOS DISPUTADOS',value:s.played,detail:`${s.wins} vitórias · ${s.draws} empates · ${s.losses} derrotas`,icon:<CalendarDays/>},{label:'VITÓRIAS',value:s.wins,detail:`${s.played?Math.round(s.wins/s.played*100):0}% de aproveitamento`,icon:<Flag/>},{label:'GOLOS MARCADOS',value:s.goalsFor,detail:`${s.goalsAgainst} golos sofridos`,icon:<Goal/>},{label:'CONQUISTAS',value:c.trophies.length,detail:'Um lugar na história',icon:<Trophy/>}]).map(x=><article className="stat-card" key={x.label}><div><span>{x.label}</span>{x.icon}</div><strong>{x.value}</strong><p>{x.detail}</p></article>)}</div><div className="home-columns"><section className="panel"><SectionTitle action={<TextLink onClick={()=>go('games')}>Calendário</TextLink>}>Próximo desafio</SectionTitle>{next?<div className="next-match"><div className="next-match-meta"><span>{next.competition}</span><span>{shortDate(next.date)}</span></div><div className="next-match-clubs"><div><Crest club={c.club} color={c.color} size={48}/><strong>{c.club}</strong></div><span>VS</span><div><Crest club={next.opponent} color="#b6ac87" size={48}/><strong>{next.opponent}</strong></div></div><p>{next.venue==='home'?'Em tua casa. Faz valer o apoio.':'Longe de casa. A mesma ambição.'}</p><button className="button outline full" onClick={()=>open('match',next.id)}>Abrir ficha do jogo<ArrowRight size={16}/></button></div>:<Empty icon={<CalendarDays/>} title="O próximo desafio espera." body="Adiciona um jogo ao calendário e começa a preparar a próxima jornada." action={<button className="text-link" onClick={()=>open('match')}>Adicionar jogo<Plus size={16}/></button>}/>}</section><section className="panel"><SectionTitle action={<TextLink onClick={()=>go('games')}>Ver todos</TextLink>}>Últimos resultados</SectionTitle>{recent.length?<div>{recent.map(m=><MatchRow key={m.id} career={c} match={m} onClick={()=>open('match',m.id)}/>)}</div>:<Empty icon={<Flag/>} title="A história começa no primeiro apito." body="Os resultados que registares vão aparecer aqui."/>}<div className="panel-foot"><span>FORMA RECENTE</span><div className="form-dots">{recent.length?recent.slice().reverse().map(m=><span key={m.id} className={`result result-${matchResult(m)}`}>{matchResult(m)}</span>):<span>—</span>}</div></div></section></div><div className="home-bottom"><section className="panel"><SectionTitle action={<TextLink onClick={()=>go('locker')}>Plantel</TextLink>}>Quem faz a diferença</SectionTitle>{leaders.length?leaders.map((p,i)=><button className="leader-row" key={p.id} onClick={()=>open('player',p.id)}><span className="leader-rank">0{i+1}</span><div className="number-avatar" style={{color:c.color}}>{p.number}</div><div><strong>{p.name}</strong><span>{p.position} · {p.stats.played} jogos</span></div><div className="leader-goals"><strong>{p.stats.goals}</strong><span>GOLOS</span></div></button>):<Empty icon={<ShirtIcon/>} title="O palco está preparado." body="Regista estatísticas individuais nos jogos para descobrir os destaques."/>}</section><button className="locker-promo" onClick={()=>go(c.mode==='player'?'objectives':'lineup')}><div><span className="eyebrow">{c.mode==='player'?'O PRÓXIMO CAPÍTULO':'A TUA IDENTIDADE EM CAMPO'}</span><h2>{c.mode==='player'?'Um objetivo de cada vez.':'Onze camisolas.'}<br/>{c.mode==='player'?'A tua ambição.':'Uma só ambição.'}</h2><span className="text-link">{c.mode==='player'?'Ver objetivos':'Preparar a equipa'}<ArrowUpRight size={18}/></span></div><div className="mini-pitch"><span/><i/><b/><div>{c.formation}</div></div><span className="promo-foot">{active.length} JOGADORES · {c.formation}</span></button></div></>;
}
export function Locker({career:c,open,update}:Props){const [search,setSearch]=useState('');const [filter,setFilter]=useState('Todos');const [view,setView]=useState('locker');const latestMatch=c.matches.filter(m=>m.status==='played').slice().sort((a,b)=>b.date.localeCompare(a.date))[0];const topPerformance=latestMatch?.performances.filter(p=>p.rating>0).slice().sort((a,b)=>b.rating-a.rating)[0];const playerOfMatch=topPerformance?c.players.find(p=>p.id===topPerformance.playerId)?.name:undefined;const hatTrickPerformance=latestMatch?.performances.find(p=>p.goals>=3);const hatTrick=hatTrickPerformance?c.players.find(p=>p.id===hatTrickPerformance.playerId)?.name:undefined;const available=c.players.filter(isAvailable);const selected=available.filter(p=>p.name.toLowerCase().includes(search.toLowerCase())&&(filter==='Todos'||filter==='Guarda-redes'&&p.position==='GR'||filter==='Defesas'&&['DC','DD','DE'].includes(p.position)||filter==='Médios'&&['MC','MDC','MCO','MD','ME'].includes(p.position)||filter==='Avançados'&&['PL','ED','EE'].includes(p.position)));
return <><PageHeader eyebrow={`${c.club} / ${c.mode==='player'?'O TEU CACIFO':'CENTRAL DE EQUIPA'}`} title="Aqui vestimos a mesma história." description="Cada camisola tem um nome. Cada nome faz parte do teu legado." action={<Add onClick={()=>open('player')}>Adicionar jogador</Add>}/><div className="locker-toolbar"><div className="tabs">{['Todos','Guarda-redes','Defesas','Médios','Avançados'].map(x=><button key={x} className={filter===x?'active':''} onClick={()=>setFilter(x)}>{x}{x==='Todos'&&<span>{available.length}</span>}</button>)}</div><div className="locker-tools"><div className="search-field"><Search size={16}/><input aria-label="Pesquisar jogador" placeholder="Procurar jogador…" value={search} onChange={e=>setSearch(e.target.value)}/></div><div className="view-switch"><button aria-label="Vista balneário" className={view==='locker'?'active':''} onClick={()=>setView('locker')}><LayoutGrid size={17}/></button><button aria-label="Vista lista" className={view==='list'?'active':''} onClick={()=>setView('list')}><List size={17}/></button></div></div></div><div className="notice small-notice">Plantel inicial e atributos de exemplo. Ajusta-os ao teu save. Camisolas originais do MyCareer; personaliza a sala e visita os teus jogadores.</div>{view==='locker'?<Suspense fallback={<div className="locker3d-shell locker3d-loading">A preparar o balneário 3D…</div>}><Locker3D players={selected} club={c.club} color={c.color} style={c.lockerStyle??DEFAULT_LOCKER_STYLE} onStyleChange={lockerStyle=>update({...c,lockerStyle})} hasRecentMatch={Boolean(latestMatch)} playerOfMatch={playerOfMatch} hatTrick={hatTrick} onSelect={id=>open('player',id)}/></Suspense>:<div className="panel table-wrap"><table><thead><tr><th>Jogador</th><th>Posição</th><th>OVR</th><th>Idade</th><th>Jogos</th><th>Golos</th><th>Assist.</th><th/></tr></thead><tbody>{selected.map(p=>{const s=playerStats(c,p.id);return <tr key={p.id}><td><button className="table-player" onClick={()=>open('player',p.id)}><span>{p.number}</span><strong>{p.name}</strong></button></td><td>{p.position}</td><td><span className="rating-badge">{p.overall}</span></td><td>{p.age}</td><td>{s.played}</td><td>{s.goals}</td><td>{s.assists}</td><td><button className="icon-button" aria-label={`Editar ${p.name}`} onClick={()=>open('player',p.id)}><Pencil size={15}/></button></td></tr>;})}</tbody></table></div>}{!selected.length&&<Empty icon={<Search/>} title="Nenhuma camisola por aqui." body="Experimenta outro nome ou outra posição."/>}<div className="page-footnote"><span>UM CLUBE. MUITAS HISTÓRIAS.</span><span>Clica numa camisola para abrir a ficha ↗</span></div></>;}
export function Lineup({career:c,open,update}:Props){
 const [slot,setSlot]=useState<number|null>(null);const [planName,setPlanName]=useState('');
 const active=c.players.filter(isAvailable);const plans=c.squadPlans??[];
 const benchIds=(c.bench??active.filter(p=>!c.lineup.includes(p.id)).map(p=>p.id)).filter(id=>active.some(p=>p.id===id)&&!c.lineup.includes(id));
 for(const player of active)if(!c.lineup.includes(player.id)&&!benchIds.includes(player.id))benchIds.push(player.id);
 const benchPlayers=benchIds.map(id=>active.find(p=>p.id===id)).filter((p):p is Player=>Boolean(p));
 const savePlan=()=>{const name=planName.trim();if(!name)return;update({...c,squadPlans:[...plans,{id:uid(),name,formation:c.formation,lineup:[...c.lineup],bench:[...benchIds]}]});setPlanName('');};
 const choosePlayer=(id:string)=>{if(slot===null)return;const lineup=[...c.lineup];const old=lineup[slot];const previous=lineup.indexOf(id);lineup[slot]=id;if(previous!==-1&&previous!==slot)lineup[previous]=old;const nextBench=benchIds.filter(x=>x!==id);if(previous===-1&&old&&!nextBench.includes(old))nextBench.unshift(old);update({...c,lineup,bench:nextBench});setSlot(null);};
 const moveBench=(index:number,step:number)=>{const next=[...benchIds];const target=index+step;if(target<0||target>=next.length)return;[next[index],next[target]]=[next[target],next[index]];update({...c,bench:next});};
 return <><PageHeader eyebrow={`${c.club} / TÁTICA`} title="As tuas ideias, em campo." description="Escolhe uma formação, posiciona os titulares e ordena o banco de suplentes." action={<select className="formation-select" aria-label="Formação" value={c.formation} onChange={e=>update({...c,formation:e.target.value})}>{Object.keys(formations).map(f=><option key={f}>{f}</option>)}</select>}/>
 <div className="saved-plans panel"><div><label htmlFor="plan-name">GUARDAR ESTE PLANTEL</label><input id="plan-name" value={planName} onChange={e=>setPlanName(e.target.value)} placeholder="Ex.: Onze para a Champions" maxLength={48}/><button className="button subtle" disabled={!planName.trim()||plans.length>=30} onClick={savePlan}><Save size={15}/>Guardar</button></div><div><label htmlFor="plan-load">PLANTEIS GUARDADOS · {plans.length}/30</label><select id="plan-load" value="" onChange={e=>{const plan=plans.find(x=>x.id===e.target.value);if(plan)update({...c,formation:plan.formation,lineup:[...plan.lineup],bench:[...(plan.bench??active.filter(p=>!plan.lineup.includes(p.id)).map(p=>p.id))]});}}><option value="">Carregar um plantel</option>{plans.map(p=><option value={p.id} key={p.id}>{p.name} · {p.formation}</option>)}</select>{plans.length>0&&<div className="saved-plan-chips">{plans.map(p=><span key={p.id}>{p.name}<button aria-label={`Apagar o plano ${p.name}`} onClick={()=>update({...c,squadPlans:plans.filter(x=>x.id!==p.id)})}><Trash2 size={12}/></button></span>)}</div>}</div></div>
 <div className="lineup-layout"><section className="pitch-panel"><div className="pitch-top"><span>ONZE INICIAL</span><span>{c.formation} · {c.lineup.filter(Boolean).length}/11</span></div><div className="football-pitch"><div className="pitch-lines"><div className="half-line"/><div className="center-circle"/><div className="penalty top"/><div className="penalty bottom"/><div className="goal-box top"/><div className="goal-box bottom"/></div>{formations[c.formation].map((pos,i)=>{const p=active.find(x=>x.id===c.lineup[i]);return <button key={i} style={{left:`${pos.x}%`,top:`${pos.y}%`}} className={`pitch-player ${slot===i?'selected':''}`} onClick={()=>setSlot(slot===i?null:i)} aria-label={`${pos.position}: ${p?.name??'Vazio'}`}><div><Shirt color={c.color} number={p?.number} keeper={pos.position==='GR'}/></div><strong>{p?.name.split(' ').slice(-1)[0]??'Escolher'}</strong><span>{pos.position}{p?` · ${p.overall}`:''}</span></button>;})}</div><div className="pitch-footer"><CircleDot size={15}/>{slot===null?'Seleciona uma posição para preparar o teu onze.':`A escolher ${formations[c.formation][slot].position}. Seleciona um jogador ao lado.`}</div></section>
 <section className="panel squad-selection"><SectionTitle>{slot===null?`Banco e reservas · ${benchPlayers.length}`:`Escolher ${formations[c.formation][slot].position}`}</SectionTitle><p className="micro-copy">{slot===null?'Ordena os suplentes pela prioridade de entrada. Clica num nome para abrir a ficha.':'Escolhe um atleta do banco ou troca com outro titular.'}</p>{slot===null?benchPlayers.map((p,i)=><div className="selection-player bench-player" key={p.id}><button className="number-avatar bench-open" onClick={()=>open('player',p.id)} aria-label={`Abrir ficha de ${p.name}`}>{p.number}</button><button className="bench-name" onClick={()=>open('player',p.id)}><strong>{p.name}</strong><span>{p.position} · Suplente {i+1}</span></button><span className="rating-badge">{p.overall}</span><div className="bench-order"><button aria-label={`Subir ${p.name}`} disabled={i===0} onClick={()=>moveBench(i,-1)}>↑</button><button aria-label={`Descer ${p.name}`} disabled={i===benchPlayers.length-1} onClick={()=>moveBench(i,1)}>↓</button></div></div>):active.map(p=><button className="selection-player" key={p.id} onClick={()=>choosePlayer(p.id)}><span className="number-avatar">{p.number}</span><div><strong>{p.name}</strong><span>{p.position} {c.lineup.includes(p.id)?'· Titular':benchIds.includes(p.id)?'· Suplente':''}</span></div><span className="rating-badge">{p.overall}</span></button>)}{slot!==null&&<button className="button subtle full" onClick={()=>{const lineup=[...c.lineup];const dropped=lineup[slot];lineup[slot]='';const next=benchIds.filter(id=>id!==dropped);if(dropped&&!next.includes(dropped))next.unshift(dropped);update({...c,lineup,bench:next});setSlot(null);}}>Deixar posição vazia</button>}</section></div></>;
}
export function Games({career:c,open,update}:Props){const [tab,setTab]=useState('Todos');const [search,setSearch]=useState('');const games=c.matches.filter(m=>(tab==='Todos'||tab==='Realizados'&&m.status==='played'||tab==='Agendados'&&m.status==='scheduled')&&`${m.opponent} ${m.competition}`.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date));const s=stats(c);return <><PageHeader eyebrow="CALENDÁRIO / DIÁRIO DE JOGO" title="Noventa minutos. Mil histórias." description="Tudo o que aconteceu em campo, guardado jornada a jornada." action={<Add onClick={()=>open('match')}>Adicionar jogo</Add>}/><div className="games-summary"><div><strong>{s.played}</strong><span>JOGADOS</span></div><div><strong className="green">{s.wins}</strong><span>VITÓRIAS</span></div><div><strong>{s.draws}</strong><span>EMPATES</span></div><div><strong className="red">{s.losses}</strong><span>DERROTAS</span></div><div><strong>{s.goalsFor}<i> : </i>{s.goalsAgainst}</strong><span>GOLOS</span></div></div><div className="toolbar"><div className="tabs">{['Todos','Realizados','Agendados'].map(t=><button key={t} className={tab===t?'active':''} onClick={()=>setTab(t)}>{t}</button>)}</div><div className="search-field"><Search size={16}/><input aria-label="Pesquisar jogos" value={search} onChange={e=>setSearch(e.target.value)} placeholder="Adversário ou competição…"/></div></div><div className="panel games-list">{games.length?games.map(m=><div className="game-record" key={m.id}><MatchRow match={m} career={c} onClick={()=>open('match',m.id)}/><button className="icon-button delete-game" aria-label={`Apagar jogo contra ${m.opponent}`} onClick={()=>{if(confirm(`Apagar o jogo contra ${m.opponent}? As estatísticas serão recalculadas.`))update({...c,matches:c.matches.filter(x=>x.id!==m.id)});}}><Trash2 size={15}/></button></div>):<Empty icon={<CalendarDays/>} title="A próxima página está em branco." body="Regista um resultado ou agenda o teu próximo desafio." action={<Add onClick={()=>open('match')}>Adicionar jogo</Add>}/>}</div><p className="micro-copy">Os totais incluem todos os jogos realizados desta carreira. Abre uma ficha para corrigir o resultado ou adicionar estatísticas.</p></>;}
export function Office({career:c,open,update}:Props){const [tab,setTab]=useState('Anotações');return <><PageHeader eyebrow={c.mode==='player'?'ESCRITÓRIO / O TEU PERCURSO':'ESCRITÓRIO / DIREÇÃO DESPORTIVA'} title="As decisões também ganham jogos." description="Ideias para amanhã. Movimentos que mudam a tua história." action={<Add onClick={()=>open(tab==='Anotações'?'note':'transfer')}>{tab==='Anotações'?'Nova anotação':'Registar transferência'}</Add>}/><div className="office-banner"><BriefcaseBusiness size={32}/><div><span className="eyebrow">À SECRETÁRIA DE</span><h2>{c.person}</h2><p>{c.club} · {c.mode==='player'?'Jogador':'Treinador'} · {c.season}</p></div><span className="office-quote">O próximo capítulo<br/>começa numa ideia.</span></div><div className="tabs space-bottom">{['Anotações','Transferências'].map(t=><button key={t} className={tab===t?'active':''} onClick={()=>setTab(t)}>{t}<span>{t==='Anotações'?c.notes.length:c.transfers.length}</span></button>)}</div>{tab==='Anotações'?(c.notes.length?<div className="notes-grid">{c.notes.map(n=><article className="note-card" key={n.id}><div><NotebookPen size={18}/><span>{shortDate(n.date)}</span></div><button className="note-content" onClick={()=>open('note',n.id)}><h2>{n.title}</h2><p>{n.body||'Adicionar os detalhes…'}</p></button><div className="note-actions"><button className="text-link" onClick={()=>open('note',n.id)}>Editar<Pencil size={14}/></button><button className="icon-button" aria-label={`Apagar ${n.title}`} onClick={()=>{if(confirm('Apagar esta anotação?'))update({...c,notes:c.notes.filter(x=>x.id!==n.id)});}}><Trash2 size={15}/></button></div></article>)}</div>:<div className="panel"><Empty icon={<NotebookPen/>} title="Há uma ideia à tua espera." body="Guarda objetivos, observações e planos para a próxima janela de transferências." action={<Add onClick={()=>open('note')}>Nova anotação</Add>}/></div>):<div className="panel">{c.mode==='player'&&<div className="notice">Este registo acompanha o mercado do clube. Para mudar o teu clube nesta versão, cria uma nova carreira e mantém a anterior no histórico.</div>}{c.transfers.length?c.transfers.slice().reverse().map(t=><div className="transfer-row" key={t.id}><span className={`transfer-icon ${t.direction==='in'?'green':'red'}`}>{t.direction==='in'?<ArrowDownLeft/>:<ArrowUpRight/>}</span><div><strong>{t.player}</strong><span>{t.direction==='in'?'De':'Para'} {t.club} · {shortDate(t.date)}</span></div><div><strong>{compactMoney(t.fee)}</strong><span>{t.operation==='loan'?'EMPRÉSTIMO':t.operation==='free'?'CUSTO ZERO':t.direction==='in'?'CONTRATAÇÃO':'SAÍDA'}{(t.installments??1)>1?` · ${t.installments} PRESTAÇÕES`:''}</span></div></div>):<Empty icon={<ArrowRight/>} title="O mercado ainda está tranquilo." body="Regista as contratações e saídas confirmadas no jogo." action={<Add onClick={()=>open('transfer')}>Registar transferência</Add>}/>}</div>}</>;}
export function Finance({career:c,open,update}:Props){const income=c.transactions.filter(t=>t.amount>0).reduce((a,t)=>a+t.amount,0);const expenses=-c.transactions.filter(t=>t.amount<0).reduce((a,t)=>a+t.amount,0);const scheduled=-c.transactions.filter(t=>t.amount<0&&t.date>today()).reduce((a,t)=>a+t.amount,0);const wages=c.players.filter(isAvailable).reduce((a,p)=>a+p.salary,0);return <><PageHeader eyebrow={c.mode==='player'?'FINANÇAS / CONTA PESSOAL':'FINANÇAS / CONTAS DO CLUBE'} title="Ambição com os pés na terra." description="Uma visão clara dos valores que registas na tua carreira." action={<Add onClick={()=>open('transaction')}>Novo movimento</Add>}/><div className="finance-grid"><div className="balance-card"><span className="eyebrow">{c.mode==='player'?'SALDO PESSOAL':'SALDO DISPONÍVEL'}</span><strong>{compactMoney(balance(c))}</strong><p>Inicial: {money(c.budget)}</p><button className="text-link" onClick={()=>open('settings')}>Ajustar valor inicial<SlidersHorizontal size={15}/></button><Wallet className="balance-watermark"/></div><div className="panel finance-stat"><span><ArrowDownLeft className="green"/> RECEITAS REGISTADAS</span><strong>{compactMoney(income)}</strong><p>Inclui prémios e saídas no mercado</p></div><div className="panel finance-stat"><span><ArrowUpRight className="red"/> DESPESAS REGISTADAS</span><strong>{compactMoney(expenses)}</strong><p>Inclui salários lançados e contratações</p></div>{scheduled>0&&<div className="panel finance-stat scheduled-finance"><span><CalendarDays/> PRESTAÇÕES FUTURAS</span><strong>{compactMoney(scheduled)}</strong><p>Ficam fora do saldo disponível até à data de pagamento</p></div>}</div><div className="panel"><SectionTitle>Livro de movimentos</SectionTitle>{c.transactions.length?<div className="table-wrap"><table><thead><tr><th>Descrição</th><th>Data</th><th>Categoria</th><th>Valor</th><th/></tr></thead><tbody>{c.transactions.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(t=><tr key={t.id}><td><strong>{t.label}</strong></td><td>{shortDate(t.date)}</td><td>{t.category}{t.date>today()&&<small className="scheduled-tag"> · AGENDADO</small>}</td><td className={t.amount>0?'green':'red'}>{t.amount>0?'+':''}{money(t.amount)}</td><td>{!c.transfers.some(x=>x.id===t.id)&&<button className="icon-button" aria-label={`Apagar ${t.label}`} onClick={()=>{if(confirm('Apagar este movimento?'))update({...c,transactions:c.transactions.filter(x=>x.id!==t.id)});}}><Trash2 size={15}/></button>}</td></tr>)}</tbody></table></div>:<Empty icon={<Wallet/>} title="Contas em dia. Livro em branco." body="Define o valor inicial e regista as receitas e despesas do teu save." action={<button className="text-link" onClick={()=>open('settings')}>Definir valor inicial<ArrowRight size={15}/></button>}/>}</div><div className="notice finance-notice"><Wallet size={18}/><span>{c.mode==='manager'?`Salários semanais do plantel: ${money(wages)}. `:''}Os valores são um registo manual; não são descontados automaticamente nem sincronizados com o jogo.</span></div></>;}
export function Trophies({career:c,open,update}:Props){const [filter,setFilter]=useState('Todas');const trophies=c.trophies.filter(t=>filter==='Todas'||filter==='Coletivas'&&t.kind==='team'||filter==='Individuais'&&t.kind==='individual');return <><PageHeader eyebrow="MUSEU / SALA DE TROFÉUS" title="O esforço passa. A glória fica." description="Um lugar para cada conquista. Uma história por trás de cada taça." action={<Add onClick={()=>open('trophy')}>Adicionar conquista</Add>}/><div className="trophy-banner"><div><span className="eyebrow">O TEU LEGADO</span><h2>{c.trophies.length}<span>momentos<br/>para a história.</span></h2><p>{c.club} · {c.person}</p></div><TrophyArt/></div><div className="tabs space-bottom">{['Todas','Coletivas','Individuais'].map(f=><button key={f} className={filter===f?'active':''} onClick={()=>setFilter(f)}>{f}</button>)}</div>{trophies.length?<div className="trophy-grid">{trophies.map(t=><article className="trophy-card" key={t.id}><span className="eyebrow">{t.kind==='team'?'TÍTULO COLETIVO':'PRÉMIO INDIVIDUAL'}</span><TrophyArt/><div className="trophy-plinth"/><h2>{t.name}</h2><p>ÉPOCA {t.season}</p><button className="icon-button trophy-delete" aria-label={`Apagar conquista ${t.name}`} onClick={()=>{if(confirm('Apagar esta conquista?'))update({...c,trophies:c.trophies.filter(x=>x.id!==t.id)});}}><Trash2 size={14}/></button></article>)}</div>:<div className="panel"><Empty title="Há espaço para o teu primeiro troféu." body="Regista os títulos e prémios que conquistares no jogo. A sala cresce contigo." action={<Add onClick={()=>open('trophy')}>Adicionar conquista</Add>}/></div>}<p className="micro-copy">Troféu ilustrativo original MyCareer. Réplicas 3D específicas de cada competição serão integradas numa próxima versão.</p></>;}
export function History({career:c,open}:Props){const events=[...c.matches.filter(m=>m.status==='played').map(m=>({id:m.id,date:m.date,title:`${c.club} ${m.goalsFor} – ${m.goalsAgainst} ${m.opponent}`,detail:`${m.competition} · ${m.venue==='home'?'Casa':'Fora'}`,type:'match' as const})),...c.transfers.map(t=>({id:t.id,date:t.date,title:`${t.direction==='in'?'Chegada':'Saída'} de ${t.player}`,detail:`${t.club} · ${money(t.fee)}`,type:'transfer' as const}))].sort((a,b)=>b.date.localeCompare(a.date));return <><PageHeader eyebrow="ARQUIVO / MEMÓRIAS DA CARREIRA" title="Uma história que merece ficar." description={`${c.name} · ${c.person} · Desde o primeiro registo.`}/><div className="history-intro"><Crest club={c.club} color={c.color} size={60}/><div><h2>{c.club}</h2><p>{c.game} · {c.season} · {c.mode==='player'?'Jogador':'Treinador'}</p></div><div><strong>{stats(c).played}</strong><span>JOGOS</span></div><div><strong>{c.trophies.length}</strong><span>CONQUISTAS</span></div></div><div className="panel"><SectionTitle>Os capítulos até agora</SectionTitle>{events.length?<div className="timeline">{events.map(ev=><button className="timeline-event" key={ev.id} onClick={()=>open(ev.type==='match'?'match':'transfer',ev.id)} disabled={ev.type==='transfer'}><span className="timeline-dot">{ev.type==='match'?<Flag size={15}/>:<ArrowRight size={15}/>}</span><div><small>{shortDate(ev.date)} {ev.date.slice(0,4)}</small><strong>{ev.title}</strong><p>{ev.detail}</p></div>{ev.type==='match'&&<ChevronRight size={16}/>}</button>)}</div>:<Empty icon={<Clock3/>} title="Ainda há tudo por escrever." body="Os teus jogos e transferências vão formar a linha do tempo desta carreira."/>}</div></>;}

export function Seasons({career:c,update}:Props){const history=c.seasons??[];const seasonCareer={...c,matches:c.matches.filter(m=>(m.season??c.season)===c.season)};const current=stats(seasonCareer);const individual=c.players.map(p=>({...p,stats:playerStats(seasonCareer,p.id)})).filter(p=>p.stats.played>0||p.stats.goals>0||p.stats.assists>0).sort((a,b)=>b.stats.goals-a.stats.goals||b.stats.assists-a.stats.assists);const next=nextSeason(c.game,c.season);const canClose=!history.some(s=>s.season===c.season)&&history.length<15;const finish=()=>{if(!canClose)return;const nextStep=next??c.season;if(!confirm(`Finalizar ${seasonLabel(c.game,c.season)}? Os jogos ficam guardados${next?' e a carreira avança para a próxima época.':' no arquivo.'}`))return;const archive={season:c.season,closedAt:today(),played:current.played,wins:current.wins,draws:current.draws,losses:current.losses,goalsFor:current.goalsFor,goalsAgainst:current.goalsAgainst,points:current.points,players:c.players.map(p=>{const s=playerStats(seasonCareer,p.id);return {playerId:p.id,...s};}).filter(p=>p.played>0||p.goals>0||p.assists>0)};update({...c,seasons:[...history,archive],season:nextStep});};return <><PageHeader eyebrow={`${c.game} / ARQUIVO`} title="Cada época deixa a sua marca." description="Fecha a temporada para guardar o resumo e abrir a próxima, sem apagar jogos ou dados." action={canClose?<Add onClick={finish}>Finalizar época</Add>:undefined}/><div className="season-current panel"><div><span className="eyebrow">ÉPOCA EM CURSO</span><h2>{seasonLabel(c.game,c.season)}</h2><p>{current.played} jogos · {current.wins} V · {current.draws} E · {current.losses} D</p></div><div className="season-current-stats"><span><strong>{current.points}</strong>PTS</span><span><strong>{current.goalsFor}:{current.goalsAgainst}</strong>GOLOS</span></div></div><div className="panel season-individuals"><SectionTitle>Estatísticas individuais · {c.season}</SectionTitle>{individual.length?<div className="table-wrap"><table><thead><tr><th>Jogador</th><th>Jogos</th><th>Golos</th><th>Assist.</th><th>Minutos</th><th>Nota média</th></tr></thead><tbody>{individual.map(p=><tr key={p.id}><td><strong>{p.name}</strong></td><td>{p.stats.played}</td><td>{p.stats.goals}</td><td>{p.stats.assists}</td><td>{p.stats.minutes}</td><td>{p.stats.rating?p.stats.rating.toFixed(1):'—'}</td></tr>)}</tbody></table></div>:<p className="micro-copy">As estatísticas dos jogadores aparecem aqui quando adicionares jogos e desempenhos.</p>}</div>{!canClose&&<div className="notice">{history.length>=15?'A carreira atingiu o limite de 15 épocas nesta edição do jogo.':'Esta época já está no arquivo.'}</div>}{canClose&&!next&&<div className="notice">Esta é a 15.ª e última época disponível para esta edição. Ao finalizar, o resumo fica guardado e a carreira termina.</div>}<div className="panel"><SectionTitle>Épocas finalizadas</SectionTitle>{history.length?<div className="season-history">{history.slice().reverse().map(s=><article key={s.season}><div><span className="eyebrow">{seasonLabel(c.game,s.season)} · FINALIZADA</span><small>Fechada em {shortDate(s.closedAt)}</small></div><strong>{s.wins}V <i>·</i> {s.draws}E <i>·</i> {s.losses}D</strong><span>{s.played} jogos</span><span>{s.goalsFor}:{s.goalsAgainst} golos</span><b>{s.points} pts</b>{s.players&&s.players.length>0&&<details className="season-players"><summary>Ver jogadores</summary><div>{s.players.slice().sort((a,b)=>b.goals-a.goals||b.assists-a.assists).map(p=><span key={p.playerId}>{c.players.find(x=>x.id===p.playerId)?.name??'Jogador'} · {p.goals} G · {p.assists} A · {p.minutes} min</span>)}</div></details>}</article>)}</div>:<Empty icon={<CalendarDays/>} title="O arquivo está pronto." body="Quando finalizares a época atual, o resumo vai aparecer aqui."/>}</div><div className="notice"><CalendarDays size={17}/><span>Season / Saison / Temporada / Stagione · os dados de cada época ficam nesta carreira e na cópia de segurança.</span></div></>;}

export function Scout({career:c,update}:Props){const reports=c.scouting??[];const [search,setSearch]=useState('');const [folder,setFolder]=useState('Todas');const [showForm,setShowForm]=useState(false);const [name,setName]=useState('');const [club,setClub]=useState('');const [position,setPosition]=useState('MC');const [age,setAge]=useState(20);const [overall,setOverall]=useState(65);const [fee,setFee]=useState('');const [estimateNote,setEstimateNote]=useState('Estimativa manual');const [newFolder,setNewFolder]=useState('Geral');const [potential,setPotential]=useState('Por avaliar');const [notes,setNotes]=useState('');const folders=['Todas',...new Set(reports.map(r=>r.folder))];const visible=reports.filter(r=>(folder==='Todas'||r.folder===folder)&&`${r.name} ${r.club} ${r.position}`.toLowerCase().includes(search.toLowerCase()));const addReport=(e:React.FormEvent)=>{e.preventDefault();if(!name.trim()||!club.trim())return;const item:ScoutReport={id:uid(),name:name.trim(),club:club.trim(),position,age:Number(age),overall:Number(overall),estimatedFee:fee===''?null:Number(fee),estimateNote:fee===''?'Sem estimativa':estimateNote.trim()||'Estimativa manual',folder:newFolder.trim()||'Geral',status:'Por observar',potential,notes:notes.trim(),date:today()};update({...c,scouting:[...reports,item]});setName('');setClub('');setFee('');setNotes('');setShowForm(false);};return <><PageHeader eyebrow="RECRUTAMENTO / OBSERVAÇÃO" title="O próximo talento pode estar à espera." description="Organiza alvos, potencial e estimativas numa lista privada desta carreira." action={<Add onClick={()=>setShowForm(!showForm)}>{showForm?'Fechar formulário':'Novo relatório'}</Add>}/><div className="notice scout-source"><Binoculars size={17}/><span>Não há uma fonte gratuita e autorizada de valores de mercado ligada. Aqui, OVR, potencial e preço são introduzidos por ti e ficam identificados como estimativas manuais.</span></div>{showForm&&<form className="panel scout-form" onSubmit={addReport}><SectionTitle>Novo jogador sob observação</SectionTitle><div className="scout-fields"><label>Nome<input required maxLength={100} value={name} onChange={e=>setName(e.target.value)}/></label><label>Clube<input required maxLength={100} value={club} onChange={e=>setClub(e.target.value)}/></label><label>Posição<select value={position} onChange={e=>setPosition(e.target.value)}>{['GR','DD','DC','DE','MDC','MC','MCO','MD','ME','ED','EE','PL'].map(p=><option key={p}>{p}</option>)}</select></label><label>Idade<input type="number" min="14" max="99" value={age} onChange={e=>setAge(Number(e.target.value))}/></label><label>OVR atual (editável)<input type="number" min="1" max="99" value={overall} onChange={e=>setOverall(Number(e.target.value))}/></label><label>Preço estimado (€)<input type="number" min="0" step="1000" placeholder="Deixar vazio se desconhecido" value={fee} onChange={e=>setFee(e.target.value)}/></label><label>Base da estimativa<input value={estimateNote} onChange={e=>setEstimateNote(e.target.value)} placeholder="Ex.: valor que observaste no jogo"/></label><label>Pasta<input maxLength={48} value={newFolder} onChange={e=>setNewFolder(e.target.value)}/></label><label>Potencial / status<input maxLength={80} value={potential} onChange={e=>setPotential(e.target.value)}/></label><label className="scout-notes">Anotações<textarea rows={2} maxLength={1000} value={notes} onChange={e=>setNotes(e.target.value)} placeholder="Pontos fortes, estilo, encaixe na equipa…"/></label></div><div className="scout-form-foot"><span>Preço apresentado como estimativa própria, não como cotação oficial.</span><button className="button primary" type="submit"><Plus size={16}/>Guardar na observação</button></div></form>}<div className="scout-toolbar"><div className="tabs">{folders.map(f=><button key={f} className={folder===f?'active':''} onClick={()=>setFolder(f)}>{f}</button>)}</div><div className="search-field"><Search size={16}/><input aria-label="Pesquisar observados" placeholder="Nome, clube ou posição…" value={search} onChange={e=>setSearch(e.target.value)}/></div></div>{visible.length?<div className="scout-grid">{visible.map(r=><article className="panel scout-card" key={r.id}><div className="scout-card-head"><span className="number-avatar">{r.position}</span><button className="icon-button" aria-label={`Remover ${r.name} do scout`} onClick={()=>update({...c,scouting:reports.filter(x=>x.id!==r.id)})}><Trash2 size={15}/></button></div><div className="scout-card-main"><span className="eyebrow">{r.club} · {r.age} ANOS</span><h2>{r.name}</h2><p>{r.position} · OVR {r.overall}</p></div><div className="scout-value"><span>PREÇO ESTIMADO</span><strong>{r.estimatedFee===null?'—':compactMoney(r.estimatedFee)}</strong><small>{r.estimateNote}</small></div><div className="scout-card-meta"><label>Pasta<select value={r.folder} onChange={e=>update({...c,scouting:reports.map(x=>x.id===r.id?{...x,folder:e.target.value}:x)})}>{[...new Set(reports.map(x=>x.folder))].map(f=><option key={f}>{f}</option>)}</select></label><label>Status<select value={r.status} onChange={e=>update({...c,scouting:reports.map(x=>x.id===r.id?{...x,status:e.target.value}:x)})}>{['Por observar','Em observação','Contactado','Prioridade','Descartado'].map(x=><option key={x}>{x}</option>)}</select></label></div><details><summary>Potencial e notas</summary><p><strong>{r.potential}</strong>{r.notes&&` · ${r.notes}`}</p></details></article>)}</div>:<div className="panel"><Empty icon={<Binoculars/>} title={reports.length?'Nenhum jogador encontrado.':'A rede ainda está vazia.'} body={reports.length?'Tenta outra pesquisa ou abre uma pasta diferente.':'Cria relatórios com dados que observaste. Uma fonte externa pode ser ligada quando validarmos acesso e licença.'} action={!reports.length?<Add onClick={()=>setShowForm(true)}>Criar primeiro relatório</Add>:undefined}/></div>}<p className="micro-copy">Os relatórios e as estimativas ficam guardados apenas nesta carreira; exporta uma cópia para os conservar.</p></>;}

export function Academy({career:c,update}:Props){const prospects=c.academy??[];const [showForm,setShowForm]=useState(false);const [name,setName]=useState('');const [position,setPosition]=useState('MC');const [age,setAge]=useState(17);const [overall,setOverall]=useState(55);const [potential,setPotential]=useState('Por avaliar');const [nation,setNation]=useState('');const [notes,setNotes]=useState('');const add=(e:React.FormEvent)=>{e.preventDefault();if(!name.trim())return;const p:AcademyProspect={id:uid(),name:name.trim(),position,age:Number(age),overall:Number(overall),potential:potential.trim()||'Por avaliar',nation:nation.trim()||'A definir',appearances:0,goals:0,assists:0,status:'Formação',notes:notes.trim()};update({...c,academy:[...prospects,p]});setName('');setNotes('');setShowForm(false);};const promote=(prospect:AcademyProspect)=>{if(c.players.some(p=>p.name.toLowerCase()===prospect.name.toLowerCase())){alert('Já existe um jogador com este nome no plantel.');return;}let number=1;const used=new Set(c.players.map(p=>p.number));while(used.has(number)&&number<99)number++;const player:Player={id:uid(),name:prospect.name,number,position:prospect.position,overall:prospect.overall,age:prospect.age,nation:prospect.nation,salary:0,contract:`${Number(c.season.slice(0,4))+1}-06-30`,active:true};update({...c,players:[...c.players,player],academy:prospects.map(p=>p.id===prospect.id?{...p,status:'Promovido'}:p)});};return <><PageHeader eyebrow={`${c.club} / FORMAÇÃO`} title="O futuro também treina aqui." description="Acompanha jovens, evolução e minutos antes de os promoveres ao plantel principal." action={<Add onClick={()=>setShowForm(!showForm)}>{showForm?'Fechar formulário':'Adicionar jovem'}</Add>}/><div className="notice">Os dados e os desempenhos são registados manualmente a partir do teu save; não existe uma base de academia ligada.</div>{showForm&&<form className="panel scout-form" onSubmit={add}><SectionTitle>Novo jogador da formação</SectionTitle><div className="scout-fields"><label>Nome<input required maxLength={100} value={name} onChange={e=>setName(e.target.value)}/></label><label>Posição<select value={position} onChange={e=>setPosition(e.target.value)}>{['GR','DD','DC','DE','MDC','MC','MCO','MD','ME','ED','EE','PL'].map(p=><option key={p}>{p}</option>)}</select></label><label>Idade<input type="number" min="14" max="23" value={age} onChange={e=>setAge(Number(e.target.value))}/></label><label>OVR atual<input type="number" min="1" max="99" value={overall} onChange={e=>setOverall(Number(e.target.value))}/></label><label>Potencial<input maxLength={50} value={potential} onChange={e=>setPotential(e.target.value)} placeholder="Ex.: 80–86"/></label><label>Nacionalidade<input maxLength={60} value={nation} onChange={e=>setNation(e.target.value)}/></label><label className="scout-notes">Anotações<textarea rows={2} maxLength={1000} value={notes} onChange={e=>setNotes(e.target.value)} placeholder="Plano individual, evolução, observações…"/></label></div><div className="scout-form-foot"><span>Os registos continuam editáveis no teu save.</span><button className="button primary" type="submit"><Plus size={16}/>Adicionar à academia</button></div></form>}{prospects.length?<div className="panel table-wrap"><table><thead><tr><th>Jovem</th><th>Posição</th><th>Idade</th><th>OVR</th><th>Potencial</th><th>Jogos</th><th>Golos</th><th>Assist.</th><th>Estado</th><th/></tr></thead><tbody>{prospects.map(p=><tr key={p.id}><td><strong>{p.name}</strong><small className="academy-nation">{p.nation}</small></td><td>{p.position}</td><td>{p.age}</td><td><input className="academy-stat-input" aria-label={`OVR ${p.name}`} type="number" min="1" max="99" value={p.overall} onChange={e=>update({...c,academy:prospects.map(x=>x.id===p.id?{...x,overall:Number(e.target.value)}:x)})}/></td><td>{p.potential}</td>{(['appearances','goals','assists'] as const).map(k=><td key={k}><input className="academy-stat-input" aria-label={`${k} ${p.name}`} type="number" min="0" value={p[k]} onChange={e=>update({...c,academy:prospects.map(x=>x.id===p.id?{...x,[k]:Number(e.target.value)}:x)})}/></td>)}<td><select aria-label={`Estado ${p.name}`} value={p.status} onChange={e=>update({...c,academy:prospects.map(x=>x.id===p.id?{...x,status:e.target.value}:x)})}>{['Formação','Em evolução','Emprestado','Promovido'].map(x=><option key={x}>{x}</option>)}</select></td><td><div className="academy-actions"><button className="icon-button" aria-label={`Promover ${p.name}`} title="Promover ao plantel principal" disabled={p.status==='Promovido'} onClick={()=>promote(p)}><ArrowUpRight size={15}/></button><button className="icon-button" aria-label={`Remover ${p.name} da academia`} onClick={()=>update({...c,academy:prospects.filter(x=>x.id!==p.id)})}><Trash2 size={15}/></button></div></td></tr>)}</tbody></table></div>:<div className="panel"><Empty icon={<ShirtIcon/>} title="Ainda não há jovens registados." body="Adiciona os jogadores da tua academia e acompanha as estatísticas da época." action={<Add onClick={()=>setShowForm(true)}>Adicionar jovem</Add>}/></div>}<p className="micro-copy">Promover cria um jogador editável no plantel e mantém o jovem no arquivo da academia com o estado Promovido.</p></>;}

export function Objectives({career:c,update}:Props){
 const goals=c.goals??[];const record=c.playerRecord??{yellowCards:0,redCards:0,matchesMissed:0,coachConfidence:50,injuries:[]};
 const [showForm,setShowForm]=useState(false);const [title,setTitle]=useState('');const [kind,setKind]=useState<CareerGoal['kind']>('personal');const [target,setTarget]=useState(10);const [progress,setProgress]=useState(0);const [notes,setNotes]=useState('');
 const [injuryName,setInjuryName]=useState('');const [injuryReturn,setInjuryReturn]=useState('');const [injuryMissed,setInjuryMissed]=useState(0);
 const add=(e:React.FormEvent)=>{e.preventDefault();if(!title.trim())return;const item:CareerGoal={id:uid(),title:title.trim(),kind,target:Number(target),progress:Number(progress),season:c.season,status:'Em curso',notes:notes.trim()};update({...c,goals:[...goals,item]});setTitle('');setNotes('');setShowForm(false);};
 const addInjury=(e:React.FormEvent)=>{e.preventDefault();if(!injuryName.trim()||!injuryReturn)return;const item={id:uid(),name:injuryName.trim(),startDate:today(),returnDate:injuryReturn,matchesMissed:Number(injuryMissed),status:'Lesionado'};update({...c,playerRecord:{...record,injuries:[...record.injuries,item],matchesMissed:record.matchesMissed+Number(injuryMissed)}});setInjuryName('');setInjuryReturn('');setInjuryMissed(0);setShowForm(false);};
 const player=c.players.find(p=>p.id===c.playerId);
 return <><PageHeader eyebrow={`${c.person} / AGENTE`} title="Escolhe o próximo destino." description="Guarda ambições pessoais, metas da época e clubes que queres alcançar." action={<Add onClick={()=>setShowForm(!showForm)}>{showForm?'Fechar formulário':'Novo objetivo ou lesão'}</Add>}/>
 <div className="objective-hero panel"><div><span className="eyebrow">O TEU PERCURSO · {c.season}</span><h2>{player?.name??c.person}</h2><p>{c.club} · OVR {player?.overall??'—'} · {player?.position??'—'}</p></div><div><span className="eyebrow">OBJETIVOS ATIVOS</span><strong>{goals.filter(g=>g.season===c.season&&g.status==='Em curso').length}</strong></div></div>
 <section className="panel player-career-status"><div className="section-title"><h3>Forma e confiança</h3><span>Registos da carreira de jogador</span></div><div className="career-status-grid"><label>Cartões amarelos<input type="number" min="0" max="999" value={record.yellowCards} onChange={e=>update({...c,playerRecord:{...record,yellowCards:Number(e.target.value)}})}/></label><label>Cartões vermelhos<input type="number" min="0" max="999" value={record.redCards} onChange={e=>update({...c,playerRecord:{...record,redCards:Number(e.target.value)}})}/></label><label>Jogos falhados<input type="number" min="0" max="9999" value={record.matchesMissed} onChange={e=>update({...c,playerRecord:{...record,matchesMissed:Number(e.target.value)}})}/></label><label>Confiança do treinador · {record.coachConfidence}%<input type="range" min="0" max="100" value={record.coachConfidence} onChange={e=>update({...c,playerRecord:{...record,coachConfidence:Number(e.target.value)}})}/></label></div></section>
 <section className="panel player-injuries"><div className="section-title"><h3>Lesões e recuperação</h3><button className="text-link" onClick={()=>setShowForm(true)}><Plus size={15}/>Adicionar lesão</button></div>{record.injuries.length?<div className="injury-list">{record.injuries.map(injury=><article key={injury.id}><div><strong>{injury.name}</strong><span>{shortDate(injury.startDate)} — regresso previsto {shortDate(injury.returnDate)} · {injury.matchesMissed} jogos previstos</span></div><select value={injury.status} aria-label={`Estado de ${injury.name}`} onChange={e=>update({...c,playerRecord:{...record,injuries:record.injuries.map(x=>x.id===injury.id?{...x,status:e.target.value}:x)}})}>{['Lesionado','Recuperação','Regressou'].map(x=><option key={x}>{x}</option>)}</select><button className="icon-button" aria-label={`Apagar lesão ${injury.name}`} onClick={()=>update({...c,playerRecord:{...record,injuries:record.injuries.filter(x=>x.id!==injury.id)}})}><Trash2 size={15}/></button></article>)}</div>:<p className="micro-copy">Ainda não há lesões registadas.</p>}</section>
 {showForm&&<div className="objective-form-grid"><form className="panel scout-form" onSubmit={add}><SectionTitle>Objetivo da carreira</SectionTitle><div className="scout-fields"><label className="scout-notes">Título / clube-alvo<input required maxLength={100} value={title} onChange={e=>setTitle(e.target.value)} placeholder="Ex.: Marcar 20 golos ou chegar ao Real Madrid"/></label><label>Tipo<select value={kind} onChange={e=>setKind(e.target.value as CareerGoal['kind'])}><option value="personal">Meta pessoal</option><option value="club-target">Clube-alvo</option></select></label><label>Alvo numérico<input type="number" min="0" value={target} onChange={e=>setTarget(Number(e.target.value))}/></label><label>Progresso atual<input type="number" min="0" value={progress} onChange={e=>setProgress(Number(e.target.value))}/></label><label className="scout-notes">Notas<textarea rows={2} maxLength={1000} value={notes} onChange={e=>setNotes(e.target.value)}/></label></div><div className="scout-form-foot"><span>Associado à época {c.season}.</span><button className="button primary" type="submit"><Plus size={16}/>Guardar objetivo</button></div></form>
 <form className="panel scout-form" onSubmit={addInjury}><SectionTitle>Registar lesão</SectionTitle><div className="scout-fields"><label className="scout-notes">Tipo de lesão<input required maxLength={80} value={injuryName} onChange={e=>setInjuryName(e.target.value)} placeholder="Ex.: Entorse do tornozelo"/></label><label>Regresso previsto<input type="date" required value={injuryReturn} onChange={e=>setInjuryReturn(e.target.value)}/></label><label>Jogos previstos fora<input type="number" min="0" max="999" value={injuryMissed} onChange={e=>setInjuryMissed(Number(e.target.value))}/></label></div><div className="scout-form-foot"><span>Registo manual, sem diagnóstico médico.</span><button className="button primary" type="submit"><Plus size={16}/>Guardar lesão</button></div></form></div>}
 <div className="notice">Objetivos e clubes-alvo são escritos por ti. O parecer do empresário baseado nos teus registos será acrescentado quando houver um modelo seguro; ainda não há IA ligada.</div>
 {goals.length?<div className="objective-grid">{goals.map(g=><article className="panel objective-card" key={g.id}><div><span className="eyebrow">{g.kind==='club-target'?'CLUBE-ALVO':'META PESSOAL'} · {g.season}</span><button className="icon-button" aria-label={`Apagar objetivo ${g.title}`} onClick={()=>update({...c,goals:goals.filter(x=>x.id!==g.id)})}><Trash2 size={15}/></button></div><h2>{g.title}</h2><label>Progresso<input type="number" min="0" max={g.target||undefined} value={g.progress} onChange={e=>update({...c,goals:goals.map(x=>x.id===g.id?{...x,progress:Number(e.target.value)}:x)})}/><span> / {g.target}</span></label><progress max={Math.max(g.target,1)} value={Math.min(g.progress,g.target)}/><select value={g.status} aria-label={`Estado de ${g.title}`} onChange={e=>update({...c,goals:goals.map(x=>x.id===g.id?{...x,status:e.target.value}:x)})}>{['Em curso','Concluído','Abandonado'].map(x=><option key={x}>{x}</option>)}</select>{g.notes&&<p>{g.notes}</p>}</article>)}</div>:<div className="panel"><Empty icon={<Flag/>} title="A tua próxima ambição começa aqui." body="Define um objetivo pessoal ou guarda um clube que gostarias de alcançar." action={<Add onClick={()=>setShowForm(true)}>Criar objetivo</Add>}/></div>}</>;
}

export function PlayerMuseum({career:c,update}:Props){
 const items=c.playerMuseum??[];const [form,setForm]=useState(false);const [kind,setKind]=useState<MuseumItem['kind']>('shirt');const [title,setTitle]=useState('');const [club,setClub]=useState('');const [season,setSeason]=useState(c.season);const [number,setNumber]=useState(10);const [color,setColor]=useState(c.color);const [detail,setDetail]=useState('');const [match,setMatch]=useState('');
 const add=(e:React.FormEvent)=>{e.preventDefault();if(!title.trim())return;const item:MuseumItem={id:uid(),kind,title:title.trim(),club:club.trim()||c.club,season:season.trim()||c.season,number:Number(number),color,detail:detail.trim(),match:match.trim()};update({...c,playerMuseum:[...items,item]});setTitle('');setDetail('');setMatch('');setForm(false);};
 return <><PageHeader eyebrow={`${c.person} / MEMÓRIAS`} title="O teu percurso merece um museu." description="Guarda as camisolas, clubes, frases e prémios que marcaram a tua carreira." action={<Add onClick={()=>setForm(!form)}>{form?'Fechar formulário':'Adicionar memória'}</Add>}/><div className="notice museum-note">As peças são representações gráficas originais do MyCareer, não réplicas oficiais. Usa este espaço para registar clubes e épocas; não carregues imagens sem autorização.</div>{form&&<form className="panel scout-form museum-form" onSubmit={add}><SectionTitle>Nova peça do museu</SectionTitle><div className="scout-fields"><label>Tipo<select value={kind} onChange={e=>setKind(e.target.value as MuseumItem['kind'])}><option value="shirt">Camisola</option><option value="scarf">Cachecol</option><option value="ball">Bola de conquista</option><option value="award">Prémio individual</option><option value="phrase">Frase / símbolo</option></select></label><label className="scout-notes">Título ou nome<input required maxLength={100} value={title} onChange={e=>setTitle(e.target.value)} placeholder="Ex.: Primeira época no clube"/></label><label>Clube / seleção<input maxLength={100} value={club} onChange={e=>setClub(e.target.value)} placeholder={c.club}/></label><label>Época<input maxLength={20} value={season} onChange={e=>setSeason(e.target.value)}/></label>{kind==='shirt'&&<><label>Número<input type="number" min="0" max="99" value={number} onChange={e=>setNumber(Number(e.target.value))}/></label><label>Cor principal<input className="museum-color" type="color" value={color} onChange={e=>setColor(e.target.value)}/></label></>}<label className="scout-notes">Jogo ou contexto<input maxLength={140} value={match} onChange={e=>setMatch(e.target.value)} placeholder="Ex.: Final europeia fora de casa"/></label><label className="scout-notes">História<textarea rows={2} maxLength={1000} value={detail} onChange={e=>setDetail(e.target.value)} placeholder="Porque esta peça importa para ti…"/></label></div><div className="scout-form-foot"><span>Época e contexto ficam ligados à peça.</span><button className="button primary" type="submit"><Plus size={16}/>Guardar no museu</button></div></form>}{items.length?<div className="museum-grid">{items.map(item=><article className="panel museum-piece" key={item.id}><div className="museum-piece-art">{item.kind==='shirt'?<Shirt color={item.color} number={item.number} name={c.person} back/>:item.kind==='award'?<TrophyArt/>:item.kind==='ball'?<div className="museum-ball"><CircleDot size={75}/></div>:item.kind==='scarf'?<div className="museum-scarf" style={{background:`linear-gradient(135deg,${item.color},#eee4c5,${item.color})`}}><span>{item.title}</span></div>:<div className="museum-phrase">{item.title.slice(0,1).toUpperCase()}</div>}</div><div className="museum-piece-copy"><span className="eyebrow">{item.club} · {item.season}</span><h2>{item.title}</h2>{item.match&&<p className="museum-match">{item.match}</p>}{item.detail&&<details><summary>Ver memória</summary><p>{item.detail}</p></details>}<button className="icon-button" aria-label={`Remover ${item.title} do museu`} onClick={()=>update({...c,playerMuseum:items.filter(x=>x.id!==item.id)})}><Trash2 size={15}/></button></div></article>)}</div>:<div className="panel"><Empty icon={<ShirtIcon/>} title="O museu começa com uma memória." body="Regista os clubes, camisolas e prémios do teu percurso. Cada peça pode guardar a época e o jogo que a tornou especial." action={<Add onClick={()=>setForm(true)}>Adicionar primeira memória</Add>}/></div>}</>;
}
